/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const plan = JSON.parse(fs.readFileSync('.exp_agent/round_01/plan.json', 'utf8'));
const report = JSON.parse(fs.readFileSync('.exp_agent/round_01/completion.json', 'utf8'));
const expected = plan.rules.flatMap(rule => rule.files.flatMap(file => file.locations.map(location => ({rule: rule.rule, path: file.relative_path, line: location.line, column: location.column}))));
const actual = report.entity_repairs.flatMap(entry => entry.locations.map(location => ({rule: entry.rule, path: entry.relative_path, line: location.line, column: location.column})));
const key = x => JSON.stringify(x);
const expectedSet = new Set(expected.map(key));
const actualSet = new Set(actual.map(key));
const missing = expected.filter(item => "'!actualSet.has(key(item)));
const extra = actual.filter(item => !expectedSet.has(key(item)));
const selectedMatches = JSON.stringify(report.selected_rules) === JSON.stringify(plan.rules.map(rule => rule.rule));
console.log(JSON.stringify({expectedLocations: expected.length, actualLocations: actual.length, expectedEntries: plan.rules.reduce((n, rule) => n + rule.files.length, 0), actualEntries: report.entity_repairs.length, selectedMatches, missing, extra}, null, 2));
process.exit(missing.length || extra.length || !selectedMatches ? 1 : 0);
NODE'
